-- Add the beginner straddle steps ("Straddle från grunden") as skill workouts.
-- They come before the existing Straddle tree for people who only get halfway down.
-- Generated by scripts/straddle-base-migration.mjs from src/skills.js; edit those, not the .sql.
-- Only new exercise ids are added. Saved workouts, XP, ranks, skill levels and baselines are unchanged.
begin;
alter function public.arc_strength_meta(text) rename to arc_strength_meta_v20;
create function public.arc_strength_meta(id text) returns jsonb
language sql immutable set search_path=public,pg_temp as $$
 select coalesce((select value from jsonb_array_elements('[{"id":"sk-straddle-base-1","name":"Fjärilen","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"core","pose":"skill","unit":"sek","thresholds":[30,60,90,120,150,180],"cue":"Sitt med fotsulorna mot varandra. Håll i fötterna och sitt lång i ryggen. Låt knäna sjunka av sig själva, tryck inte. Mål: 3 × 30 s. Logga den svagare sidan efter båda sidor och följ målets tempo.","skillTree":"straddle-base","skillLevel":1,"skillAnim":"butterfly","skillSets":3,"skillAmount":30},{"id":"sk-straddle-base-2","name":"Sittande straddle, rak rygg","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"core","pose":"skill","unit":"sek","thresholds":[45,90,135,180,225,270],"cue":"Benen så brett det går utan smärta, knäna får vara lätt böjda. Händerna i golvet bakom dig. Sitt lång och andas lugnt. Mål: 3 × 45 s. Logga den svagare sidan efter båda sidor och följ målets tempo.","skillTree":"straddle-base","skillLevel":2,"skillAnim":"straddle-sit","skillSets":3,"skillAmount":45},{"id":"sk-straddle-base-3","name":"Sidoutfall","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"core","pose":"skill","unit":"reps","thresholds":[8,16,24,32,40,48],"cue":"Brett steg åt sidan. Böj ena knät och sätt dig bakåt, det andra benet rakt. Gå bara så djupt det känns bra. Mål: 2 × 8 per sida. Logga den svagare sidan efter båda sidor och följ målets tempo.","skillTree":"straddle-base","skillLevel":3,"skillAnim":"side-lunge","skillSets":2,"skillAmount":8},{"id":"sk-straddle-base-4","name":"Bred fällning med stöd","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"core","pose":"skill","unit":"sek","thresholds":[30,60,90,120,150,180],"cue":"Fötterna brett isär. Händerna på en stol, låda eller block. Fäll från höften med lång rygg. Mål: 3 × 30 s. Logga den svagare sidan efter båda sidor och följ målets tempo.","skillTree":"straddle-base","skillLevel":4,"skillAnim":"supported-fold","skillSets":3,"skillAmount":30},{"id":"sk-straddle-base-5","name":"Halv pancake","muscle":"Rörlighet","equipment":"Kroppsvikt","family":"core","pose":"skill","unit":"sek","thresholds":[30,60,90,120,150,180],"cue":"Sitt bredbent, knäna får vara lätt böjda. Gå fram med händerna tills du känner stretch. Stanna där och andas ut. Mål: 3 × 30 s. Logga den svagare sidan efter båda sidor och följ målets tempo.","skillTree":"straddle-base","skillLevel":5,"skillAnim":"half-pancake","skillSets":3,"skillAmount":30}]'::jsonb) where value->>'id'=id), public.arc_strength_meta_v20(id))
$$;
revoke all on function public.arc_strength_meta_v20(text) from public,anon,authenticated;
create or replace function public.training_expansion_ready() returns integer language sql stable as $$select 21$$;
notify pgrst,'reload schema';
commit;
